from datetime import datetime

def run(ctx):
    # 1. Navigate to Orders List and establish state with Status=Complete filter
    state = ctx.gui("Go to Sales > Orders", success={"entity": "Orders"})

    # 2. Query all completed orders within the date range (Jan 2023 - May 2023)
    rows = ctx.query(
        state,
        entity="Orders",
        fields=["Purchase Date"],
        filters={
            "Status": "Complete",
            "Purchase Date from": "01/01/2023",
            "Purchase Date to": "05/31/2023"
        }
    )

    # 3. Aggregate counts by month name
    monthly_counts = {}
    for row in rows:
        # Parse ISO-like date string returned by provider (e.g., "2023-01-15 10:00:00")
        try:
            dt = datetime.strptime(row["Purchase Date"].split()[0], "%Y-%m-%d")
        except (ValueError, IndexError):
            continue

        month_name = dt.strftime("%B")
        monthly_counts[month_name] = monthly_counts.get(month_name, 0) + 1

    # 4. Format result as list of objects sorted chronologically
    result = []
    for month in ["January", "February", "March", "April", "May"]:
        if month in monthly_counts:
            result.append({"month": month, "count": monthly_counts[month]})

    return result

